def summarize(name):
 p=W/'runs'/name;m=json.loads((p/'manifest.json').read_text());log=(W/'logs'/f'{name}.log').read_text();drops=[float(v) for v in re.findall(r'Worstcase IR drop:\s*([\d.eE+-]+)',log)]
 short=json.loads((p/'floorplan.odb.shorts.json').read_text()) if (p/'floorplan.odb.shorts.json').exists() else None
 boxes=[(t['x']-30,t['y']-30,t['x']+t['w']+30,t['y']+t['h']+30) for t in m['tiles']]
 overlaps=sum(min(a[2],b[2])>max(a[0],b[0]) and min(a[3],b[3])>max(a[1],b[1]) for i,a in enumerate(boxes) for b in boxes[i+1:]);legal=not overlaps and all(a[0]>=700 and a[1]>=700 and a[2]<=m['die_width_mm']*1000-700 and a[3]<=m['die_height_mm']*1000-700 for a in boxes)
 r={k:v for k,v in m.items() if k not in ['tiles','pads']};r.update(placement_legal_check=legal,macro_overlap_count=overlaps,pdn_pass=all(f'W3_CONNECTIVITY_{net}_PASS' in log for net in ['VDD','VSS']),ir_solver_pass=all(f'W3_IR_{net}_PASS' in log for net in ['VDD','VSS']),worst_ir_drop_v=drops[0] if len(drops)==2 else None,worst_ground_rise_v=drops[1] if len(drops)==2 else None,combined_worst_bound_v=sum(drops) if len(drops)==2 else None,ir_5pct_pass=len(drops)==2 and sum(drops)<.165,short_check=short,execution=json.loads((p/'execution.json').read_text()) if (p/'execution.json').exists() else None,artifacts={k:str((p/v).relative_to(W)) for k,v in [('def','floorplan.def'),('odb','floorplan.odb'),('png','floorplan.png'),('heatmap','ir_heatmap.png'),('tcl','floorplan.tcl'),('lef','macros.lef'),('VDD_voltages','VDD_voltage.rpt'),('VSS_voltages','VSS_voltage.rpt')]})
 r['physical_screen_pass']=legal and r['pdn_pass'] and r['ir_solver_pass'] and r['ir_5pct_pass'] and short is not None and short['short_count']==0
 return r
