res=dict(updated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='measured_input_abstract_floorplan_screen; complete_recognizer_not_proven',measured_input_floorplan=dict(selection='measured320',memory='sram_open_macro',levers='off',reason='Tallest new bank with sampled slow-corner evidence in snapshot; no bank has complete timing qualification. Open SRAM LEF dimensions preserve model numerics.',source_hashes=cfg['source_hashes'],source_final_check=checks,input_refresh_audit='input_refresh_audit.json',inventory_totals=cfg['inventory_totals'],memory_allocation=cfg['memory_allocation_summary'],engine_model=cfg['engine_model'],block_area_table=blockrows,area_table=rows,physical_cases=physical,preserved_failed_cases=[failed]+other_failures,packing_search=json.loads((W/'measured_outline_search.json').read_text()),reticle_assumption_mm=[26,33],one_reticle_fits=False,two_reticles_fit=False,minimum_reticle_count_by_block_area_only=3,complete_macro_timing_proven=False,power_measured=False),physical_cases=physical,area_table=rows,baseline_memory_complete=True,historical_report='historical_pre_measured_RESULTS.md',full_recognizer_on_one_die_proven=False)
